from __future__ import annotations

from dataclasses import dataclass
from typing import TypeAlias

import pytest


@dataclass
class Num:
    v: int


@dataclass
class Add:
    l: Expr
    r: Expr


@dataclass
class Mul:
    l: Expr
    r: Expr


Expr: TypeAlias = Num | Add | Mul


def eval_expr(e: Expr) -> int:
    """Evaluate an expression tree of Num, Add, and Mul nodes to an int."""
    if isinstance(e, Num):
        return e.v
    if isinstance(e, Add):
        return eval_expr(e.l) + eval_expr(e.r)
    if isinstance(e, Mul):
        return eval_expr(e.l) * eval_expr(e.r)
    raise TypeError(f"unknown expression node: {e!r}")


def test_eval_num() -> None:
    assert eval_expr(Num(5)) == 5


def test_eval_add() -> None:
    assert eval_expr(Add(Num(2), Num(3))) == 5


def test_eval_mul_negative() -> None:
    assert eval_expr(Mul(Num(4), Num(-2))) == -8


def test_eval_nested() -> None:
    expr = Add(Mul(Num(2), Num(3)), Mul(Num(4), Add(Num(1), Num(1))))
    assert eval_expr(expr) == 14
